server.createContext("/products", exchange -> {
    if (exchange.getRequestMethod().equals("POST")) {
        String requestBody = new String(exchange.getRequestBody().readAllBytes());
        // requestBody: {"name":"Mysz bezprzewodowa","price":89.99} - BEZ id
        long newId = 7; // serwer nadaje ID
        String responseBody = "{\"id\":" + newId + ",\"name\":\"Mysz bezprzewodowa\",\"price\":89.99}";
        respond(exchange, 201, responseBody); // 201 Created + PELNA reprezentacja
    }
});

// Styl "gola tablica" - prosty, bezposredni
[{"id":1,"name":"Klawiatura"},{"id":2,"name":"Monitor"}]

// Styl "koperta" - miejsce na metadane od samego poczatku
{
  "data": [{"id":1,"name":"Klawiatura"},{"id":2,"name":"Monitor"}],
  "meta": {"total": 2, "page": 1}
}

